WITH b AS (SELECT CAST(date_parse(concat(a.fechalocalautorizacion,a.horalocalautorizacion),'%y%m%d%H%i%s') AS timestamp)+INTERVAL '3' HOUR AS ts,TRIM(a.codrespuestaautorizacion) AS cr,TRIM(a.codtipomensajeautorizacion) AS cmsg,NULLIF(TRIM(a.codrespuestaiss),'') AS ciss,NULLIF(TRIM(a.nrorechazointerno),'') AS nri,CASE WHEN a.INSTRMTYP IN('VD','VK','V6','VB','VN','SR','VC') THEN 'Visa' WHEN a.INSTRMTYP IN('MD','MC','MS','MK') THEN 'Mastercard' WHEN a.INSTRMTYP='AX' THEN 'Amex' WHEN a.INSTRMTYP='PA' THEN 'Cabal' WHEN a.INSTRMTYP='UC' THEN 'UPI' ELSE 'Otra' END AS marca_f,TRIM(a.codbancoemisor) AS cbe_f,CASE WHEN length(TRIM(a.codrespuestaiss))=1 THEN '0'||TRIM(a.codrespuestaiss) WHEN length(TRIM(a.codrespuestaiss))>=2 THEN substr(TRIM(a.codrespuestaiss),length(TRIM(a.codrespuestaiss))-1,2) ELSE NULL END AS ciss_norm FROM payway_poststage_prod_db.ctx_autorizaciones_eps a WHERE a.fecha BETWEEN date_format(date_add('hour',-3,$__timeFrom()),'%Y-%m-%d') AND date_format(date_add('hour',-3,$__timeTo()),'%Y-%m-%d') AND TRIM(a.codprocesoautorizacion1) NOT IN('92','30') AND TRIM(a.codtipomensajeautorizacion)<>'1420' AND (COALESCE(NULLIF('${cuit:raw}',''),'-1')='-1' OR EXISTS(SELECT 1 FROM prisma_ab_analytics_prod_db.establecimiento e WHERE TRY_CAST(TRIM(a.nroestablecimiento) AS INTEGER)=e.nro_establecimiento AND TRY_CAST(REPLACE(e.cuit_establecimiento_host,'-','') AS BIGINT)=TRY_CAST('${cuit:raw}' AS BIGINT))) AND ('${establecimiento:raw}'='' OR TRIM(a.nroestablecimiento)='${establecimiento:raw}')),
filt AS (SELECT * FROM b WHERE 1=1 AND ('${marca:text}'='All' OR marca_f IN (${marca:sqlstring})) AND ('${banco:text}'='All' OR cbe_f IN (${banco:sqlstring})) AND ('${motivo_emisor:text}'='All' OR ciss_norm IN (${motivo_emisor:sqlstring})) AND ('${motivo_adqte:text}'='All' OR nri IN (${motivo_adqte:sqlstring})))
SELECT ROUND(100.0*SUM(CASE WHEN cr IN('0000','0400','0900') THEN 1 ELSE 0 END)/NULLIF(COUNT(*),0),2) AS taa FROM filt WHERE ts>=$__timeFrom() AND ts<$__timeTo();

